def maxrect(mask):
 h=len(mask); w=len(mask[0]); best=(0,None)
 # brute all rectangles
 for t in range(h):
  for b in range(t,h):
   for l in range(w):
    for r in range(l,w):
     if all(mask[y][x] for y in range(t,b+1) for x in range(l,r+1)):
      a=(b-t+1)*(r-l+1)
      if a>best[0]:best=(a,(t,b,l,r))
 return best

def ranks(g):
