def transform(grid):
    """Join broken aligned runs of the non-background color, using 2 for gaps."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # Initial horizontal and vertical runs are delimited by original markers.
    hlines = {}
    vlines = {}
    for r in range(h):
        xs = [c for c in range(w) if grid[r][c] == marker]
        if len(xs) >= 2:
            hlines[r] = [min(xs), max(xs)]
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        if len(ys) >= 2:
            vlines[c] = [min(ys), max(ys)]

    # Extend each horizontal run to the closest vertical run beyond either end.
    for r, span in hlines.items():
        left, right = span
        lefts = [c for c in vlines if c < left]
        rights = [c for c in vlines if c > right]
        if lefts:
            span[0] = max(lefts)
        if rights:
            span[1] = min(rights)

    # Join vertical runs to the closest horizontal run above/below when their
    # columns fall within that horizontal run (including its extension).
    for c, span in vlines.items():
        above = [r for r, (lo, hi) in hlines.items() if r < span[0] and lo <= c <= hi]
        below = [r for r, (lo, hi) in hlines.items() if r > span[1] and lo <= c <= hi]
        if above:
            span[0] = max(above)
        if below:
            span[1] = min(below)

    # Paint the missing cells along every completed stroke.
    for r, (lo, hi) in hlines.items():
        for c in range(lo, hi + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    for c, (lo, hi) in vlines.items():
        for r in range(lo, hi + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    return out

