def transform(grid):
    """Complete horizontal/vertical strokes and extend their ends to nearest perpendicular strokes."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # Lines are determined only from the original marker cells.
    rows = {r: [c for c in range(w) if grid[r][c] == color]
            for r in range(h) if sum(grid[r][c] == color for c in range(w)) >= 2}
    cols = {c: [r for r in range(h) if grid[r][c] == color]
            for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 2}
    hs = {r: [min(cs), max(cs)] for r, cs in rows.items()}
    vs = {c: [min(rs), max(rs)] for c, rs in cols.items()}

    # Extend each horizontal stroke to the nearest existing vertical stroke
    # beyond each end, and each vertical stroke to nearest horizontal strokes.
    for r, span in hs.items():
        left = [c for c in vs if c < span[0]]
        right = [c for c in vs if c > span[1]]
        if left:
            span[0] = max(left)
        if right:
            span[1] = min(right)
    for c, span in vs.items():
        above = [r for r in hs if r < span[0]]
        below = [r for r in hs if r > span[1]]
        if above:
            span[0] = max(above)
        if below:
            span[1] = min(below)

    for r, (a, b) in hs.items():
        for c in range(a, b + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    for c, (a, b) in vs.items():
        for r in range(a, b + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    return out

def transform(grid):
    """Complete broken horizontal/vertical strokes, then join perpendicular strokes."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    row_marks = {r: [c for c, v in enumerate(grid[r]) if v == color]
                 for r in range(h)}
    col_marks = {c: [r for r in range(h) if grid[r][c] == color]
                 for c in range(w)}

    # Rows with several foreground pixels indicate horizontal strokes.
    hrows = {r for r, cs in row_marks.items() if len(cs) >= 3}
    # A column is a stroke when it has markers outside those horizontal strokes.
    vcols = {c for c, rs in col_marks.items()
             if len(rs) >= 2 and any(r not in hrows for r in rs)}
    # Two-point rows are strokes only when not simply the endpoints of two
    # vertical strokes (those dots belong to the verticals instead).
    for r, cs in row_marks.items():
        if len(cs) == 2 and not (cs[0] in vcols and cs[1] in vcols):
            hrows.add(r)

    hs = {r: [min(row_marks[r]), max(row_marks[r])] for r in hrows}
    vs = {c: [min(col_marks[c]), max(col_marks[c])] for c in vcols}

    # Extend each horizontal stroke to the nearest perpendicular stroke beyond
    # either endpoint.
    for r, span in hs.items():
        left = [c for c in vcols if c < span[0]]
        right = [c for c in vcols if c > span[1]]
        if left:
            span[0] = max(left)
        if right:
            span[1] = min(right)

    # Extend vertical strokes to the nearest horizontal strokes in their axes.
    for c, span in vs.items():
        above = [r for r, (lo, hi) in hs.items() if r < span[0] and lo <= c <= hi]
        below = [r for r, (lo, hi) in hs.items() if r > span[1] and lo <= c <= hi]
        if above:
            span[0] = max(above)
        if below:
            span[1] = min(below)

    for r, (lo, hi) in hs.items():
        for c in range(lo, hi + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    for c, (lo, hi) in vs.items():
        for r in range(lo, hi + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    return out

