def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    ink = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    # Horizontal bars are the rows containing at least three ink markers.
    bars = [r for r in range(h) if sum(v == ink for v in grid[r]) >= 3]
    if not bars:
        return out
    for r in bars:
        cols = [c for c, v in enumerate(grid[r]) if v == ink]
        for c in range(min(cols), max(cols) + 1):
            if out[r][c] == bg:
                out[r][c] = 2

    # Complete the two outer vertical rails of the bar pattern.
    left = min(c for r in bars for c, v in enumerate(grid[r]) if v == ink)
    right = max(c for r in bars for c, v in enumerate(grid[r]) if v == ink)
    top, bottom = min(bars), max(bars)
    for c in {left, right}:
        for r in range(top, bottom + 1):
            # A top-edge marker separated from the rail below is an isolated
            # top-bar detail, not a missing cell of the vertical rail.
            if top == 0 and r == 1 and grid[0][c] == ink and grid[1][c] == bg:
                continue
            if out[r][c] == bg:
                out[r][c] = 2
    return out

