def _canon(cells):
    # Shape signature invariant under rotation and reflection.
    pts = list(cells)
    forms = []
    for reflect in (1, -1):
        for k in range(4):
            q = []
            for r, c in pts:
                x, y = r, reflect * c
                for _ in range(k):
                    x, y = y, -x
                q.append((x, y))
            mr = min(x for x, y in q)
            mc = min(y for x, y in q)
            forms.append(tuple(sorted((x-mr, y-mc) for x, y in q)))
    return min(forms)

def _components(g, bg):
    h, w = len(g), len(g[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r,c) in seen:
                continue
            col = g[r][c]
            q = [(r,c)]
            seen.add((r,c))
            cells = []
            while q:
                x,y = q.pop()
                cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and g[nx][ny] == col:
                        seen.add((nx,ny)); q.append((nx,ny))
            rs = [x for x,y in cells]; cs = [y for x,y in cells]
            comps.append({'color':col, 'cells':cells, 'box':(min(rs),min(cs),max(rs),max(cs)), 'sig':_canon(cells)})
    return comps

