def transform(grid):
    """Mark the missing continuation of a repeated horizontal run with 1."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Detect pairs of rows with the same left edge and run of the same
    # non-background color, where one run is a strict extension of the other.
    # The shorter row's unfilled suffix is the missing continuation.
    for i in range(h):
        vals = [v for v in grid[i] if v != bg]
        if not vals:
            continue
        color = max(set(vals), key=vals.count)
        cols = [c for c, v in enumerate(grid[i]) if v == color]
        if not cols:
            continue
        lo, hi = min(cols), max(cols)
        # Require a contiguous run from the first colored cell to the row edge
        # or a single isolated starter; compare against other rows.
        for j in range(h):
            if i == j:
                continue
            other = [c for c, v in enumerate(grid[j]) if v == color]
            if not other or min(other) != lo:
                continue
            ohi = max(other)
            # The fuller row supplies a horizontal continuation template.
            if ohi > hi and all(grid[j][c] == color for c in range(lo, ohi + 1)):
                if all(grid[i][c] == color for c in range(lo, hi + 1)):
                    for c in range(hi + 1, ohi + 1):
                        if grid[i][c] == bg:
                            out[i][c] = 1
    return out

def transform(grid):
    """Mark a truncated horizontal color run's missing rightward continuation."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Compare horizontal runs of each foreground color. A shorter run with
    # the same (or immediately adjacent) left edge as a longer run indicates
    # a truncated copy; mark its missing right-hand portion with 1.
    for r, row in enumerate(grid):
        for color in set(row) - {bg}:
            positions = [c for c, v in enumerate(row) if v == color]
            if not positions:
                continue
            # Use the first contiguous run, rather than spanning intervening
            # background/color pixels.
            start = positions[0]
            end = start
            while end + 1 < w and row[end + 1] == color:
                end += 1
            for rr, other in enumerate(grid):
                if rr == r:
                    continue
                # Find a solid run of this color on the comparison row.
                for c in range(max(0, start - 1), min(w, start + 2)):
                    if other[c] != color:
                        continue
                    e = c
                    while e + 1 < w and other[e + 1] == color:
                        e += 1
                    if e > end and c <= start and end + 1 <= w:
                        for x in range(end + 1, e + 1):
                            if row[x] == bg:
                                out[r][x] = 1
    return out

