def transform(grid):
    """Expand diagonal color clues into a periodic diagonal tiling."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c, v) for r, row in enumerate(grid)
             for c, v in enumerate(row) if v]
    if not cells:
        return [row[:] for row in grid]

    # The clues are monochrome diagonal runs; choose their common direction.
    groups = []
    for key_fn in (lambda r, c: c - r, lambda r, c: r + c):
        tracks = {}
        for r, c, color in cells:
            tracks.setdefault(key_fn(r, c), []).append(color)
        score = sum(len(v) ** 2 for v in tracks.values())
        groups.append((score, key_fn, tracks))
    _, key_fn, tracks = max(groups, key=lambda item: item[0])

    colors = {}
    for key, vals in tracks.items():
        counts = {v: vals.count(v) for v in set(vals)}
        colors[key] = max(counts, key=counts.get)

    # Find the shortest repeating period consistent with all observed tracks.
    period = None
    for p in range(1, max(h, w) * 2 + 1):
        residues = {}
        consistent = True
        for key, color in colors.items():
            residue = key % p
            if residue in residues and residues[residue] != color:
                consistent = False
                break
            residues[residue] = color
        if consistent and len(residues) == p:
            period = p
            break
    if period is None:
        # A robust fallback: use the observed tracks as a repeating motif.
        period = len(colors)
        residues = {key % period: color for key, color in colors.items()}
        if len(residues) != period:
            return [row[:] for row in grid]

    motif = {}
    for key, color in colors.items():
        motif[key % period] = color
    # The shortest consistent period may include unobserved residues. Fill any
    # such slots by extending the nearest observed motif color.
    known = sorted(motif)
    for residue in range(period):
        if residue not in motif:
            nearest = min(known, key=lambda k: min((residue-k) % period, (k-residue) % period))
            motif[residue] = motif[nearest]

    return [[motif[key_fn(r, c) % period] for c in range(w)] for r in range(h)]

