def _period(colors_by_key):
    """Smallest fully specified period consistent with all clue keys."""
    if not colors_by_key:
        return None
    max_period = max(max(colors_by_key) - min(colors_by_key) + 1, 1)
    for period in range(1, max_period + 1):
        residues = {}
        consistent = True
        for key, color in colors_by_key.items():
            residue = key % period
            if residue in residues and residues[residue] != color:
                consistent = False
                break
            residues[residue] = color
        if consistent and len(residues) == period:
            return period
    return None

