def _period(colors):
    if not colors:
        return None
    span = max(colors)-min(colors)+1
    for p in range(1, span+1):
        residues = {}
        for k,v in colors.items():
            x=k%p
            if x in residues and residues[x] != v:
                break
            residues[x]=v
        else:
            if len(residues)==p:
                return p
    return None

